hooks.command:
$input_json = [Console]::In.ReadToEnd() | ConvertFrom-Json
$path = $input_json.tool_input.file_path
if ($path -and ($path -match '(^|[\\/])\.env$') -and ($path -notmatch '\.env\.example$')) {
  $output = @{ hookSpecificOutput = @{ hookEventName = 'PreToolUse'; permissionDecision = 'deny'; permissionDecisionReason = '.env manuell bearbeiten -- nicht ueber Claude.' } }
  $output | ConvertTo-Json -Depth 5 -Compress
}

$input_json = [Console]::In.ReadToEnd() | ConvertFrom-Json
$path = $input_json.tool_input.file_path
if (-not $path) { exit 0 }
$norm = $path -replace '/', '\'
if ($norm -notmatch '\.py$') { exit 0 }
if ($norm -match '\\(tmp|\.venv|\.worktrees|graphify-out|staticfiles|__pycache__|migrations)\\') { exit 0 }
if ($norm -match '\\(accounts|core|sheets|wiki)\\') { $app = $Matches[1] } else { exit 0 }
Set-Location 'C:\Prv\pnp\RogueTraider\Character sheet\Wissensdatenbank'
& '.venv\Scripts\python.exe' -m pytest -q "$app/tests" 2>&1 | Out-String
